const finale = { active: false, shot: 0, victim: null, killer: null, killerDown: false, heir: false, call: null, focus: null, onDone: null, t0: 0, shotT0: 0, dur1: 0, dur2: 0, tok: 0, hint: null, onSkip: null, move: null, prevNear: null };
