  fill.addColorStop(0, `rgba(${L.fill}, 0.06)`); fill.addColorStop(1, `rgba(${L.fill}, 0.30)`);
  g.fillStyle = fill; g.beginPath(); g.arc(R, R, R * 0.86, 0, Math.PI * 2); g.fill();
  g.save(); g.shadowColor = `rgba(${L.glow}, 1)`; g.shadowBlur = S * 0.05;
