  let px = S * 0.15; g.font = `${px}px ${family}`;
  const widest = Math.max(...lines.map((l) => g.measureText(l).width)); if (widest > S * 0.62) { px *= S * 0.62 / widest; g.font = `${px}px ${family}`; }
  const lh = px * 1.12, y0 = c.height / 2 - (lines.length - 1) * lh / 2;
