    el.innerHTML = '<svg viewBox="0 0 100 100" aria-hidden="true"><circle class="pr-track" cx="50" cy="50" r="40"/><circle class="pr-fill" cx="50" cy="50" r="40" pathLength="100"/></svg><div class="pr-text">TELEPORTING</div>';
